// velas (modelo OBJ) dentro de la iglesia y chimenea de la cabana
static void draw_candles(void)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(58.0f, 57.0f, 6.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    if (fabsf(px - 58.0f) > 24.0f || fabsf(pz - 62.0f) > 24.0f) return;
    static const float cc[4][3] = { { 240.f, 232.f, 205.f }, { 190.f, 150.f, 70.f }, { 30.f, 30.f, 30.f }, { 255.f, 220.f, 120.f } };
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    static const float cx[4] = { 56.5f, 57.2f, 58.8f, 59.5f };
    static V vv[CD_NV];
    for (int n = 0; n < 4; n++) {
        for (int i = 0; i < CD_NV; i++)
            vv[i] = mk(cx[n] + (float)CD_v[i][0] * 0.0007f, 1.06f + ((float)CD_v[i][1] - 90.0f) * 0.0007f, 57.1f + (float)CD_v[i][2] * 0.0007f, white, 0.25f);
        for (int k = 0; k < CD_NT; k++) {
            const unsigned short *t = CD_t[k];
            if (t[3] == 3) continue;                                // la llama ahora es un sprite animado
            const float *c = cc[t[3]];
            float sh = (float)t[4] / 255.0f;
            V v[3];
            for (int j = 0; j < 3; j++) {
                v[j] = vv[t[j]];
                if (t[3] == 3) { v[j].r = c[0]; v[j].g = c[1]; v[j].b = c[2]; }
                else { v[j].r *= c[0] * sh; v[j].g *= c[1] * sh; v[j].b *= c[2] * sh; }
            }
            tri_cam(v[0], v[1], v[2]);
        }
    }
}

static void draw_chimney(void)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(52.6f, 262.0f, 6.0f, fminf(draw_lim, (gfx_pd[gfx] * rd_k)))) return;
    static const float white[3] = { 1.0f, 1.0f, 1.0f };
    static V vv[CM_NV];
    const float S = 0.0017f;
    for (int i = 0; i < CM_NV; i++)       // el frente del modelo (+z) mira hacia +x (dentro de la cabana)
        vv[i] = mk(52.1f + ((float)CM_v[i][2] + 260.0f) * S, (float)CM_v[i][1] * S, 262.0f - (float)CM_v[i][0] * S, white, 0.0f);
    for (int k = 0; k < CM_NT; k++) {
        const unsigned short *t = CM_t[k];
        float sh = (float)t[4] / 255.0f;
        V v[3];
        for (int j = 0; j < 3; j++) {
            v[j] = vv[t[j]];
            v[j].r *= 120.f * sh; v[j].g *= 108.f * sh; v[j].b *= 98.f * sh;
        }
        tri_cam(v[0], v[1], v[2]);
    }
}

