static void key_rgb_of(int code, float *o)       // color de la llave: 1..4 = llaves de color, 5..7 = llaves finales (plata azulada)
{
    if (code >= 5) { o[0] = 170.f; o[1] = 226.f; o[2] = 245.f; }
    else { o[0] = key_rgb[code - 1][0]; o[1] = key_rgb[code - 1][1]; o[2] = key_rgb[code - 1][2]; }
}

// Llave tirada en el suelo (sin brillo)
static void draw_key_floor(float x, float z, float a, int code)
{
    float col[3], ca = cosf(a), sa = sinf(a);
    const float s = 0.42f / 13100.0f;   // 0.42 m de largo
    key_rgb_of(code, col);
    for (int f = 0; f < 108; f++) {
        float p[4][3], fc[3];
        for (int j = 0; j < 4; j++) {
            const short *m = kmv[kmf[f][j]];
            float lx = (float)m[1] * s, lz = (float)m[2] * s, hy = ((float)m[0] + 1004.0f) * s;
            p[j][0] = x + lx * ca + lz * sa; p[j][1] = 0.0f + hy + 0.004f; p[j][2] = z - lx * sa + lz * ca;
        }
        float k = (float)kms[f] / 255.0f;
        fc[0] = col[0] * k; fc[1] = col[1] * k; fc[2] = col[2] * k;
        quad_sub(p, fc, 1, 0.05f);
    }
}

// Llave en la mano (vista en primera persona, como en Granny): sube desde abajo cuando la agarras
static void draw_key_hand(float t)
{
    static float up[2];
    int sl = pl_cur & 1, tgt = carry > 0;
    up[sl] += ((float)tgt - up[sl]) * 0.16f;
    if (up[sl] < 0.02f) return;
    float e = up[sl] * up[sl] * (3.0f - 2.0f * up[sl]), col[3];
    key_rgb_of(carry > 0 ? carry : 1, col);
    rd_th = 0.55f + 0.55f * (1.0f - e); rd_ya = -0.30f - 0.3f * (1.0f - e);
    rd_ox = -0.17f + 0.010f * walk_amp * sinf(walk_ph + 0.5f);
    rd_oy = -0.20f - 0.45f * (1.0f - e) + 0.008f * walk_amp * sinf(2.0f * walk_ph + 0.4f) - 0.015f * step_imp + sinf(t * 1.4f) * 0.002f;
    rd_oz = 0.42f;
    const float s = 0.34f / 13100.0f;
    float pt[4][3];
    vm_mode = 1;
    {   // mano (bloque de piel) agarrando la argolla
        float sk[3] = { hand_col[4][0], hand_col[4][1], hand_col[4][2] }, sk2[3] = { hand_col[2][0], hand_col[2][1], hand_col[2][2] };
        rd_box(0.0f, -0.050f, 0.030f, 0.036f, 0.034f, 0.030f, sk, sk2);
        rd_box(0.040f, -0.045f, 0.000f, 0.010f, 0.026f, 0.018f, sk, sk2);
        rd_box(-0.040f, -0.045f, 0.000f, 0.010f, 0.026f, 0.018f, sk, sk2);
    }
    for (int f = 0; f < 108; f++) {
        float fc[3], k = (float)kms[f] / 255.0f;
        fc[0] = col[0] * k; fc[1] = col[1] * k; fc[2] = col[2] * k;
        for (int j = 0; j < 4; j++) {
            const short *m = kmv[kmf[f][j]];
            rd_pt((float)m[2] * s, -(float)m[1] * s + 0.03f, (float)m[0] * s, pt[j]);
        }
        V v[4];
        for (int j = 0; j < 4; j++) { v[j].x = pt[j][0]; v[j].y = pt[j][1]; v[j].z = pt[j][2]; v[j].r = fc[0]; v[j].g = fc[1]; v[j].b = fc[2]; }
        tri_cam(v[0], v[1], v[2]); tri_cam(v[0], v[2], v[3]);
    }
    vm_mode = 0;
}

static void draw_key(float x, float z, float fy, float a)
{
    static const float gold[3] = { 170.f, 226.f, 245.f };      // llave final: plata azulada (la amarilla es la de la puerta del noreste)
    static const float dark[3] = { 120.f, 168.f, 196.f };
    const float em = 0.32f;
    const float y0 = fy + 0.015f, y1 = fy + 0.095f;
    const float R = 0.15f;                                    // radio medio de la argolla
    for (int k = 0; k < 8; k++) {                             // argolla: 8 barras formando un octagono con hueco
        float ang = k * (PI_F / 4.0f);
        key_part(x, z, a, -0.42f + R * cosf(ang), R * sinf(ang), -(ang + PI_F * 0.5f),
                 0.068f, 0.040f, y0, y1, gold, em);
    }
    key_part(x, z, a, -0.22f, 0.0f, 0.0f, 0.030f, 0.075f, y0, y1 + 0.012f, dark, em);   // cuello
    key_part(x, z, a,  0.18f, 0.0f, 0.0f, 0.400f, 0.032f, y0, y1, gold, em);            // caña
    key_part(x, z, a,  0.50f, 0.080f, 0.0f, 0.050f, 0.050f, y0, y1, dark, em);          // dientes
    key_part(x, z, a,  0.37f, 0.070f, 0.0f, 0.040f, 0.040f, y0, y1, dark, em);
}

// ---------------- Cartel del mapa (al inicio) ----------------
static void draw_lockers(void)
{
    if (cur_layer != 0 && !climbing) return;
    static const float body[3] = {  74.f,  92.f, 100.f };
    static const float door_c[3] = { 88.f, 110.f, 120.f };
    static const float dark[3] = {  14.f,  16.f,  18.f };
    static const float knob[3] = { 190.f, 190.f, 194.f };
    for (int i = 0; i < 2 * NLOCK; i++) {
        if (i == hide_id) continue;
        float cx = lk_x(i), cz = lk_z(i);
        if (!in_view(cx, cz, 1.5f, (gfx_pd[gfx] * rd_k))) continue;
        int fxv = LKF(i, 2), fzv = LKF(i, 3);
        float hx = fxv ? LK_D * 0.5f : LK_W * 0.5f, hz = fxv ? LK_W * 0.5f : LK_D * 0.5f;
        box_rot(cx, cz, 0.0f, 0.0f, 0.0f, hx, hz, 0.0f, LK_H, body, 0.0f);
        float fo = LK_D * 0.5f + 0.012f;                                   // la puerta, pegada al frente
        float pcx = fxv * fo, pcz = fzv * fo;
        float phx = fxv ? 0.012f : LK_W * 0.5f - 0.05f, phz = fxv ? LK_W * 0.5f - 0.05f : 0.012f;
        box_rot(cx, cz, 0.0f, pcx, pcz, phx, phz, 0.06f, LK_H - 0.06f, door_c, 0.0f);
        for (int k = 0; k < 3; k++) {                                      // rejillas
            float vy = LK_H - 0.30f - k * 0.10f, vo = LK_D * 0.5f + 0.026f;
            float vhx = fxv ? 0.006f : 0.28f, vhz = fxv ? 0.28f : 0.006f;
            box_rot(cx, cz, 0.0f, fxv * vo, fzv * vo, vhx, vhz, vy, vy + 0.04f, dark, 0.0f);
        }
        float ko = LK_D * 0.5f + 0.03f, side = LK_W * 0.5f - 0.14f;      // manija
        float kx = fxv * ko + (fxv ? 0.0f : side), kz = fzv * ko + (fxv ? side : 0.0f);
        box_rot(cx, cz, 0.0f, kx, kz, fxv ? 0.02f : 0.03f, fxv ? 0.03f : 0.02f, 1.0f, 1.2f, knob, 0.0f);
    }
}

static void draw_frenzy_hud(void)
{
    if (state != 0) return;
    if (frenzy_w > 0.0f) {                                                 // cuenta atras: busca un casillero
        char cb[40];
        snprintf(cb, sizeof cb, "BUSCA UN CASILLERO: %d", (int)ceilf(frenzy_w));
        draw_text_c(H * 0.20f + 46.0f, cb, 2, GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0));
    } else if (frenzy_t > 0.0f && frenzy_msg <= 0 && ((frame_no / 10) & 1)) {
        draw_text_c(H * 0.20f + 46.0f, "CORRE", 2, GS_SETREG_RGBAQ(230, 40, 30, 0x80, 0));
    }
    if (frenzy_msg <= 0) return;
    int on = (frenzy_msg > 150) ? ((frame_no / 4) & 1) : 1;               // al principio parpadea
    int a = frenzy_msg < 40 ? frenzy_msg * 255 / 40 : 255;
    if (on) {
        draw_text_c(H * 0.20f + 3.0f, "VIENE POR TI", 5, GS_SETREG_RGBAQ(0, 0, 0, 0x80, 0));
        draw_text_c(H * 0.20f, "VIENE POR TI", 5, GS_SETREG_RGBAQ(230 * a / 255, 20 * a / 255, 20 * a / 255, 0x80, 0));
    }
}

static void draw_locker_hud(void)
{
    draw_frenzy_hud();
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), wc = GS_SETREG_RGBAQ(200, 200, 205, 0x80, 0);
    if (hide_id >= 0) {                                      // dentro: oscuridad con las rendijas de la puerta
        u64 k = GS_SETREG_RGBAQ(2, 3, 4, 0x80, 0);
        float y0 = H * 0.40f, sh = 15.0f, gap = 28.0f, xa = W * 0.20f, xb = W * 0.80f;
        float yb = y0 + 2.0f * gap + sh;
        gsKit_prim_sprite(gsGlobal, 0.0f, 0.0f, W, y0, 16777150, k);
        gsKit_prim_sprite(gsGlobal, 0.0f, yb, W, H, 16777150, k);
        gsKit_prim_sprite(gsGlobal, 0.0f, y0, xa, yb, 16777150, k);
        gsKit_prim_sprite(gsGlobal, xb, y0, W, yb, 16777150, k);
        for (int i = 0; i < 2; i++) gsKit_prim_sprite(gsGlobal, xa, y0 + sh + i * gap, xb, y0 + (i + 1) * gap, 16777150, k);
        draw_text_c(H - 30.0f, "ESCONDIDO   CUADRADO: SALIR", 1, wc);
        return;
    }
    if (!map_open && code_door < 0 && pick_near() >= 0) {
        draw_text_c(H - 34.0f, pick_near() >= 100 || items[pick_near()].kind == 0 ? "CUADRADO: AGARRAR LLAVE" : "CUADRADO: AGARRAR PAPEL", 2, yc);
        return;
    }
    if (carry && !map_open && code_door < 0) {
        if (pick_near2(1) >= 0 && pick_near() < 0) { draw_text_c(H - 34.0f, "YA LLEVAS UNA LLAVE   R3: SOLTAR", 2, yc); return; }
        draw_text(20.0f, H - 20.0f, "R3: SOLTAR LLAVE", 1, GS_SETREG_RGBAQ(160, 160, 166, 0x80, 0));
    }
    if (locker_near() >= 0 && door_near() < 0 && !board_near()) {
        if (hide_hold > 0.0f) {                              // barra de carga: 1 segundo
            float bw = 120.0f, bx = (W - bw) * 0.5f, by = H - 50.0f;
            gsKit_prim_sprite(gsGlobal, bx - 2.0f, by - 2.0f, bx + bw + 2.0f, by + 8.0f, 16777000, BLACK);
            gsKit_prim_sprite(gsGlobal, bx, by, bx + bw * clampf(hide_hold, 0.0f, 1.0f), by + 6.0f, 16777010, yc);
        }
        draw_text_c(H - 34.0f, "MANTEN CUADRADO: ESCONDERTE", 2, yc);
    }
}

static void draw_map_board(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(MAPB_X, MAPB_Z, 2.0f, (gfx_pd[gfx] * rd_k))) return;
    static const float wood[3]  = {  96.f,  66.f,  40.f };
    static const float board[3] = { 128.f,  92.f,  58.f };
    static const float paper[3] = { 222.f, 204.f, 158.f };
    static const float ink[3]   = {  70.f,  52.f,  34.f };
    static const float mark[3]  = { 200.f,  50.f,  40.f };
    float pe = has_map ? 0.20f : 0.30f + 0.10f * sinf(t * 3.0f);    // el papel llama la atencion hasta que lo tomas
    box_rot(MAPB_X - 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);     // postes
    box_rot(MAPB_X + 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX, 0.05f, 0.95f, 2.05f, board, 0.0f);          // tablero
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX + 0.12f, 0.20f, 2.05f, 2.12f, wood, 0.0f);   // techito
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.062f, 0.95f, 0.010f, 1.10f, 1.95f, paper, pe);           // el mapa (cara hacia +z, donde apareces)
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0775f, 0.03f, 0.004f, 1.18f, 1.87f, ink, pe * 0.7f);     // trazos de tinta
    box_rot(MAPB_X, MAPB_Z, 0.0f, -0.35f, 0.0775f, 0.50f, 0.004f, 1.50f, 1.54f, ink, pe * 0.7f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.40f, 0.0775f, 0.05f, 0.004f, 1.20f, 1.30f, mark, 0.4f);        // marca roja
}

// Avisos en pantalla: tomar el mapa / como abrirlo
static void draw_map_hud(void)
{
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), wc = GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0);
    if (has_map) {                                           // icono pequeno + boton
        gsKit_prim_sprite(gsGlobal, 20.0f, 62.0f, 38.0f, 74.0f, 16777000, BLACK);
        gsKit_prim_sprite(gsGlobal, 21.0f, 63.0f, 37.0f, 73.0f, 16777010, GS_SETREG_RGBAQ(214, 196, 150, 0x80, 0));
        gsKit_prim_sprite(gsGlobal, 24.0f, 66.0f, 34.0f, 67.0f, 16777020, GS_SETREG_RGBAQ(90, 70, 45, 0x80, 0));
        gsKit_prim_sprite(gsGlobal, 24.0f, 69.0f, 31.0f, 70.0f, 16777020, GS_SETREG_RGBAQ(90, 70, 45, 0x80, 0));
        draw_text(44.0f, 64.0f, "TRIANGULO: MAPA", 1, GS_SETREG_RGBAQ(190, 190, 195, 0x80, 0));
    } else if (board_near()) {
        draw_text_c(H - 34.0f, "CUADRADO: TOMAR EL MAPA", 2, yc);
    }
    if (map_msg > 0) {
        draw_text_c(H * 0.28f, "MAPA OBTENIDO", 3, yc);
        draw_text_c(H * 0.28f + 30.0f, "TRIANGULO: ABRIR / CERRAR", 2, wc);
    }
}

// ---------------- Pantalla del mapa (TRIANGULO) ----------------
// Superficie a la izquierda y alcantarilla a la derecha. El eje X va invertido en pantalla:
// en este motor, al mirar hacia -Z el lado +X queda a tu izquierda, y asi el mapa coincide con lo que ves.
static u32 mapc[2][MH][MW];                 // color de cada celda (0xRRGGBB), calculado una sola vez
static int map_cached, sew_x0, sew_z0, sew_x1, sew_z1;

static void map_prepare(void)
{
    if (map_cached) return;
    sew_x0 = MW; sew_z0 = MH; sew_x1 = -1; sew_z1 = -1;
    for (int l = 0; l < 2; l++)
        for (int z = 0; z < MH; z++)
            for (int x = 0; x < MW; x++) {
                CellInfo c = cell_info((l ? map1 : map0)[z][x], l);
                int rock = (c.kind == 2 && !c.fdraw);
                int r, g, b;
                if (rock) { r = c.wr; g = c.wg; b = c.wb; } else { r = c.fr; g = c.fg; b = c.fb; }
                if (l && rock) { r = 12; g = 16; b = 14; }            // alcantarilla: la roca es fondo oscuro, los tuneles se ven claros
                else { r = r * 3 / 2 + 10; g = g * 3 / 2 + 10; b = b * 3 / 2 + 10; }
                if (r > 255) r = 255;
                if (g > 255) g = 255;
                if (b > 255) b = 255;
                mapc[l][z][x] = ((u32)r << 16) | ((u32)g << 8) | (u32)b;
                if (l && !rock) {                                     // recuadro que ocupa la alcantarilla
                    if (x < sew_x0) sew_x0 = x;
                    if (x > sew_x1) sew_x1 = x;
                    if (z < sew_z0) sew_z0 = z;
                    if (z > sew_z1) sew_z1 = z;
                }
            }
    if (sew_x1 < 0) { sew_x0 = 0; sew_z0 = 0; sew_x1 = MW - 1; sew_z1 = MH - 1; }
    sew_x0 = sew_x0 > 0 ? sew_x0 - 1 : 0;
    sew_z0 = sew_z0 > 0 ? sew_z0 - 1 : 0;
    sew_x1 = sew_x1 < MW - 1 ? sew_x1 + 1 : MW - 1;
    sew_z1 = sew_z1 < MH - 1 ? sew_z1 + 1 : MH - 1;
    map_cached = 1;
}

typedef struct { float ox, oy, s; int x0, z0, x1, z1; } MapPan;     // un panel: origen en pantalla, pixeles por celda, celdas que muestra
static float mpx(const MapPan *m, float u) { return m->ox + ((float)(m->x1 + 1) - u) * m->s; }   // u en celdas (con decimales)
static float mpy(const MapPan *m, float v) { return m->oy + (v - (float)m->z0) * m->s; }

static void map_panel(int layer, const MapPan *m)           // celdas iguales seguidas = un solo sprite
{
    for (int z = m->z0; z <= m->z1; z++) {
        float ya = m->oy + (float)(z - m->z0) * m->s, yb = m->oy + (float)(z - m->z0 + 1) * m->s;
        int x = m->x0;
        while (x <= m->x1) {
            u32 c = mapc[layer][z][x];
            int xe = x + 1;
            while (xe <= m->x1 && mapc[layer][z][xe] == c) xe++;
            gsKit_prim_sprite(gsGlobal, m->ox + (float)(m->x1 + 1 - xe) * m->s, ya,
                              m->ox + (float)(m->x1 + 1 - x) * m->s, yb, 16777000,
                              GS_SETREG_RGBAQ((c >> 16) & 255, (c >> 8) & 255, c & 255, 0x80, 0));
            x = xe;
        }
    }
}

static void map_frame(const MapPan *m, u64 col)
{
    float xa = m->ox - 1.0f, ya = m->oy - 1.0f;
    float xb = m->ox + (float)(m->x1 - m->x0 + 1) * m->s + 1.0f, yb = m->oy + (float)(m->z1 - m->z0 + 1) * m->s + 1.0f;
    gsKit_prim_sprite(gsGlobal, xa, ya, xb, ya + 1.0f, 16777050, col);
    gsKit_prim_sprite(gsGlobal, xa, yb - 1.0f, xb, yb, 16777050, col);
    gsKit_prim_sprite(gsGlobal, xa, ya, xa + 1.0f, yb, 16777050, col);
    gsKit_prim_sprite(gsGlobal, xb - 1.0f, ya, xb, yb, 16777050, col);
}

static void map_sq(const MapPan *m, float u, float v, float r, u64 col)   // marcador cuadrado con borde negro
{
    float x = mpx(m, u), y = mpy(m, v);
    gsKit_prim_sprite(gsGlobal, x - r - 1.0f, y - r - 1.0f, x + r + 1.0f, y + r + 1.0f, 16777100, BLACK);
    gsKit_prim_sprite(gsGlobal, x - r, y - r, x + r, y + r, 16777110, col);
}

static void map_label(const MapPan *m, float u, float v, const char *txt)   // texto centrado en (u,v)
{
    float x = mpx(m, u) - text_w(txt, 1) * 0.5f, y = mpy(m, v) - 3.5f;
    draw_text(x + 1.0f, y + 1.0f, txt, 1, BLACK);
    draw_text(x, y, txt, 1, GS_SETREG_RGBAQ(255, 245, 190, 0x80, 0));
}

static void map_legend(float x, float y, u64 col, const char *txt)
{
    gsKit_prim_sprite(gsGlobal, x - 1.0f, y - 1.0f, x + 7.0f, y + 7.0f, 16777100, BLACK);
    gsKit_prim_sprite(gsGlobal, x, y, x + 6.0f, y + 6.0f, 16777110, col);
    draw_text(x + 11.0f, y, txt, 1, GS_SETREG_RGBAQ(215, 215, 220, 0x80, 0));
}

static void draw_map_screen(void)
{
    map_prepare();
    gsKit_clear(gsGlobal, GS_SETREG_RGBAQ(8, 10, 14, 0x80, 0));
    int sw = sew_x1 - sew_x0 + 1, sh = sew_z1 - sew_z0 + 1;
    float gap = 2.0f;
    float s = fminf((H - 26.0f) / (float)MH, (W - 20.0f) / ((float)MW + gap + (float)sw));
    if (s < 1.0f) s = 1.0f;
    float x00 = floorf((W - ((float)MW + gap + (float)sw) * s) * 0.5f), y00 = 14.0f;
    MapPan A = { x00, y00, s, 0, 0, MW - 1, MH - 1 };
    MapPan B = { x00 + ((float)MW + gap) * s, y00, s, sew_x0, sew_z0, sew_x1, sew_z1 };

    u64 off = GS_SETREG_RGBAQ(150, 155, 165, 0x80, 0);
    map_panel(0, &A);
    map_panel(1, &B);
    map_frame(&A, off);
    map_frame(&B, off);
    draw_text(A.ox, 4.0f, "SUPERFICIE", 1, off);
    draw_text(B.ox, 4.0f, "ALCANTARILLA", 1, off);

    float r = fmaxf(2.0f, s * 0.9f);                          // tamano de los marcadores
    u64 c_well = GS_SETREG_RGBAQ(255, 190, 50, 0x80, 0), c_exit = GS_SETREG_RGBAQ(110, 255, 140, 0x80, 0);
    for (int i = 0; i < NMH; i++) {                           // pozos (escaleras): salen en las dos capas
        float u = (float)manholes[i][0] + 0.5f, v = (float)manholes[i][1] + 0.5f;
        map_sq(&A, u, v, r, c_well);
        map_sq(&B, u, v, r, c_well);
    }
    map_sq(&A, EXIT_X / CS, EXIT_Z / CS, r, c_exit);          // caseta de la antena
    map_sq(&A, SPAWN_X / CS, SPAWN_Z / CS, r, GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0));   // inicio / cartel

    map_label(&A, slot_xz[6][0] / CS, slot_xz[6][1] / CS - 5.0f, "CABANA");
    map_label(&A, slot_xz[7][0] / CS - 8.0f, slot_xz[7][1] / CS - 13.0f, "CUEVA");
    map_label(&A, EXIT_X / CS + 2.0f, EXIT_Z / CS - 4.5f, "ANTENA");
    map_label(&A, SPAWN_X / CS, SPAWN_Z / CS + 2.4f, "INICIO");

    float lx = B.ox, ly = B.oy + (float)sh * s + 10.0f;       // leyenda bajo la alcantarilla
    if (ly + 8.0f < H - 14.0f) { map_legend(lx, ly, c_well, "POZO / ESCALERA"); ly += 11.0f; }
    if (ly + 8.0f < H - 14.0f) { map_legend(lx, ly, c_exit, "ANTENA"); ly += 11.0f; }
    if (ly + 8.0f < H - 14.0f) { map_legend(lx, ly, GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0), "INICIO"); }
    if (map_ind) {         // indicador de jugador: punto parpadeante + flecha de hacia donde miras
        const MapPan *pp = cur_layer ? &B : &A;
        float u = px / CS, v = pz / CS, fx = sinf(yaw), fz = cosf(yaw);
        u64 c_me = ((frame_no / 20) & 1) ? GS_SETREG_RGBAQ(255, 60, 50, 0x80, 0) : GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0);
        for (int k = 1; k <= 3; k++) map_sq(pp, u + fx * k * 1.6f, v + fz * k * 1.6f, fmaxf(1.5f, r * (0.7f - 0.15f * k)), c_me);
        map_sq(pp, u, v, r * 1.3f, c_me);
        map_label(pp, u, v - 3.0f, "TU");
    }
    draw_text_c(H - 11.0f, "TRIANGULO: CERRAR", 1, GS_SETREG_RGBAQ(190, 190, 195, 0x80, 0));
}

// ---------------- Puertas, llaves, notas y candado: dibujo ----------------
static void draw_doors(void)
{
    for (int i = 0; i < ND; i++) {
        const Door *d = &doors[i];
        if (d->layer != cur_layer && !climbing) continue;
        if (!in_view(d->x, d->z, d->hw + 1.0f, (gfx_pd[gfx] * rd_k))) continue;
        float fy = d->layer ? SEWER_Y : 0.0f;
        float h = d->layer ? 3.4f : cell_info(map0[d->cz][d->cx], 0).ceil;
        if (h < 2.0f) h = 2.4f;
        float col[3], bright[3];
        if (d->type == 2) { col[0] = 70.f; col[1] = 78.f; col[2] = 84.f; bright[0] = 150.f; bright[1] = 230.f; bright[2] = 255.f; }
        else if (d->type == 0) for (int k = 0; k < 3; k++) { col[k] = key_rgb[d->id][k] * 0.55f; bright[k] = key_rgb[d->id][k]; }
        else { col[0] = 104.f; col[1] = 72.f; col[2] = 44.f; bright[0] = 150.f; bright[1] = 150.f; bright[2] = 158.f; }
        if (d->cx == 14 && d->cz == 19) {                        // puerta de la iglesia: color de llave, a toda la altura del portal
            h = 8.4f;
        }
        float base = d->orient ? PI_F * 0.5f : 0.0f;
        float hx = d->orient ? d->x : d->x - d->hw;          // bisagra: la puerta gira hacia adentro del edificio
        float hz = d->orient ? d->z + d->hw : d->z;
        float a = base + door_ang[i];
        box_rot(hx, hz, a, d->hw, 0.0f, d->hw * 0.98f, 0.09f, fy, fy + h, col, 0.10f);
        if (door_open[i]) continue;
        if (d->type == 2) {                                     // puerta final: tres ranuras (una por llave final) que se encienden
            int got = notes_used[0] + notes_used[1] + notes_used[2];
            for (int k = 0; k < 3; k++) {
                float on[3] = { 150.f, 230.f, 255.f }, off[3] = { 40.f, 40.f, 44.f };
                box_rot(hx, hz, a, d->hw + (k - 1) * 0.55f, 0.0f, 0.16f, 0.13f, fy + 1.1f, fy + 1.9f, k < got ? on : off, k < got ? 0.9f : 0.05f);
            }
            box_rot(hx, hz, a, d->hw, 0.0f, 0.9f, 0.12f, fy + 2.4f, fy + 2.55f, bright, 0.5f);
        } else if (d->type == 0)                                // placa del color de la llave
            box_rot(hx, hz, a, d->hw * 1.7f, 0.0f, 0.22f, 0.12f, fy + 1.0f, fy + 1.6f, bright, 0.45f);
        else {                                                  // candado
            box_rot(hx, hz, a, d->hw * 1.7f, 0.0f, 0.14f, 0.13f, fy + 0.95f, fy + 1.25f, bright, 0.30f);
            box_rot(hx, hz, a, d->hw * 1.7f, 0.0f, 0.03f, 0.13f, fy + 1.25f, fy + 1.45f, bright, 0.30f);
        }
    }
}

static void draw_items(float t)
{
    if (cur_layer != 0 && !climbing) return;
    for (int i = 0; i < NIT; i++) {
        if (item_got[i]) continue;
        const Item *it = &items[i];
        if (!in_view(it->x, it->z, 0.8f, (gfx_pd[gfx] * rd_k))) continue;
        float y = 0.03f, a = 0.6f + (float)i * 1.37f;               // en el suelo, quietas
        if (it->kind == 0) {                                    // llave en el suelo (modelo 3D)
            draw_key_floor(it->x, it->z, a, 1 + it->id);
        } else {                                                // papel con un codigo
            float col[3] = { 235.f, 235.f, 225.f };
            box_rot(it->x, it->z, a, 0.0f, 0.0f, 0.12f, 0.16f, y, y + 0.02f, col, 0.35f);
        }
    }
}

static void msg_text(int id, char *buf, int n)
{
    buf[0] = '\0';
    if (id >= 1 && id <= 4) snprintf(buf, n, "NECESITAS LLAVE %s", key_name[id - 1]);
    else if (id == 13) snprintf(buf, n, "PUERTA FINAL: FALTAN %d LLAVES FINALES", 3 - (notes_used[0] + notes_used[1] + notes_used[2]));
    else if (id == 16) snprintf(buf, n, "LLAVE FINAL PUESTA %d DE 3", notes_used[0] + notes_used[1] + notes_used[2]);
    else if (id == 17) snprintf(buf, n, "YA LLEVAS UNA LLAVE (R3: SOLTAR)");
    else if (id == 14) snprintf(buf, n, "LA PUERTA FINAL SE ABRE...");
    else if (id == 15) snprintf(buf, n, "LLAVE FINAL AGARRADA");
    else if (id == 10) snprintf(buf, n, "CODIGO INCORRECTO");
    else if (id == 11) snprintf(buf, n, "PUERTA ABIERTA");
    else if (id == 12) snprintf(buf, n, "CANDADO ABIERTO");
    else if (id == 40) snprintf(buf, n, "LUZ ULTRAVIOLETA");
    else if (id == 41) snprintf(buf, n, "LUZ NORMAL");
    else if (id >= 20 && id <= 23) snprintf(buf, n, "LLAVE %s", key_name[id - 20]);
    else if (id == 30 || id == 31) snprintf(buf, n, "CODIGO %s: %04d", code_name[id - 30], code_num[id - 30]);
}

// ---------------- EMOJIS (caras amarillas dibujadas con triangulos) ----------------
enum { EY_DOT, EY_WIDE, EY_SQUINT, EY_ARC, EY_LINE, EY_WINK };
enum { MO_SMILE, MO_OPEN, MO_FROWN, MO_FLAT, MO_WAVY, MO_O, MO_TONGUE, MO_BIG, MO_ZIG, MO_SMIRK, MO_YAWN };
static const unsigned char emoji_tab[30][2] = {
    {EY_DOT, MO_OPEN},    {EY_DOT, MO_SMILE},   {EY_DOT, MO_FROWN},   {EY_DOT, MO_WAVY},    {EY_DOT, MO_ZIG},
    {EY_WIDE, MO_TONGUE}, {EY_LINE, MO_TONGUE}, {EY_SQUINT, MO_BIG},  {EY_SQUINT, MO_O},    {EY_SQUINT, MO_WAVY},
    {EY_DOT, MO_FLAT},    {EY_SQUINT, MO_SMILE},{EY_ARC, MO_OPEN},    {EY_SQUINT, MO_SMIRK},{EY_ARC, MO_TONGUE},
    {EY_SQUINT, MO_TONGUE},{EY_WINK, MO_SMIRK}, {EY_SQUINT, MO_OPEN}, {EY_WINK, MO_SMILE},  {EY_SQUINT, MO_FROWN},
    {EY_DOT, MO_O},       {EY_ARC, MO_FROWN},   {EY_LINE, MO_O},      {EY_WIDE, MO_ZIG},    {EY_LINE, MO_SMIRK},
    {EY_WIDE, MO_YAWN},   {EY_WIDE, MO_FROWN},  {EY_SQUINT, MO_ZIG},  {EY_DOT, MO_WAVY},    {EY_LINE, MO_YAWN} };

static void em_ell(float cx, float cy, float rx, float ry, float a0, float a1, int seg, u64 c, int z)   // sector de elipse relleno
{
    for (int j = 0; j < seg; j++) {
        float t0 = a0 + (a1 - a0) * j / seg, t1 = a0 + (a1 - a0) * (j + 1) / seg;
        gsKit_prim_triangle_gouraud_3d(gsGlobal, cx, cy, z, cx + cosf(t0) * rx, cy + sinf(t0) * ry, z,
                                       cx + cosf(t1) * rx, cy + sinf(t1) * ry, z, c, c, c);
    }
}
static void em_line(float x0, float y0, float x1, float y1, float th, u64 c, int z)
{
    float dx = x1 - x0, dy = y1 - y0, l = sqrtf(dx * dx + dy * dy);
    if (l < 0.01f) return;
    float nx = -dy / l * th * 0.5f, ny = dx / l * th * 0.5f;
    gsKit_prim_triangle_gouraud_3d(gsGlobal, x0 + nx, y0 + ny, z, x1 + nx, y1 + ny, z, x1 - nx, y1 - ny, z, c, c, c);
    gsKit_prim_triangle_gouraud_3d(gsGlobal, x0 + nx, y0 + ny, z, x1 - nx, y1 - ny, z, x0 - nx, y0 - ny, z, c, c, c);
}
static void em_arc(float cx, float cy, float rx, float ry, float a0, float a1, int n, float th, u64 c, int z)   // arco con grosor
{
    float px_ = cx + cosf(a0) * rx, py_ = cy + sinf(a0) * ry;
    for (int j = 1; j <= n; j++) {
        float t = a0 + (a1 - a0) * j / n, x = cx + cosf(t) * rx, y = cy + sinf(t) * ry;
        em_line(px_, py_, x, y, th, c, z);
        px_ = x; py_ = y;
    }
}
static void em_zig(float cx, float cy, float w, float amp, int n, float th, u64 c, int z)                     // linea en zigzag
{
    float x0 = cx - w, y0 = cy;
    for (int j = 1; j <= n; j++) {
        float x = cx - w + 2.0f * w * j / n, y = cy + ((j & 1) ? -amp : amp);
        em_line(x0, y0, x, y, th, c, z);
        x0 = x; y0 = y;
    }
}

static void draw_emoji(float cx, float cy, float r, int id, int z)
{
    if (id < 0 || id >= 30 || r < 2.0f) return;
    const u64 yel = GS_SETREG_RGBAQ(255, 206, 66, 0x80, 0), rim = GS_SETREG_RGBAQ(205, 140, 18, 0x80, 0);
    const u64 blk = GS_SETREG_RGBAQ(26, 16, 6, 0x80, 0), red = GS_SETREG_RGBAQ(226, 62, 62, 0x80, 0);
    const float PI2 = 6.2831853f;
    int seg = r < 14.0f ? 12 : 20;
    em_ell(cx, cy, r, r, 0.0f, PI2, seg, rim, z);
    em_ell(cx, cy, r * 0.93f, r * 0.93f, 0.0f, PI2, seg, yel, z);
    float th = r * 0.085f; if (th < 1.2f) th = 1.2f;
    int ey = emoji_tab[id][0], mo = emoji_tab[id][1];
    float ex = r * 0.34f, eyy = cy - r * 0.18f;
    for (int k = -1; k <= 1; k += 2) {                                   // ojos (k = -1 izquierdo, +1 derecho)
        float x = cx + k * ex;
        int kind = ey;
        if (ey == EY_WINK) kind = (k < 0) ? EY_DOT : EY_ARC;
        if (kind == EY_DOT)  em_ell(x, eyy, r * 0.085f, r * 0.11f, 0.0f, PI2, 8, blk, z);
        else if (kind == EY_WIDE) em_ell(x, eyy, r * 0.13f, r * 0.16f, 0.0f, PI2, 8, blk, z);
        else if (kind == EY_SQUINT) {                                    // > <
            float d = r * 0.13f;
            em_line(x - k * d, eyy - d, x + k * d, eyy, th, blk, z);
            em_line(x + k * d, eyy, x - k * d, eyy + d, th, blk, z);
        } else if (kind == EY_ARC) em_arc(x, eyy + r * 0.06f, r * 0.13f, r * 0.12f, 3.14159f, PI2, 6, th, blk, z);
        else if (kind == EY_LINE) em_line(x - r * 0.12f, eyy, x + r * 0.12f, eyy, th, blk, z);
    }
    float my = cy + r * 0.30f;
    switch (mo) {
    case MO_SMILE: em_arc(cx, my - r * 0.14f, r * 0.38f, r * 0.30f, 0.18f * 3.14159f, 0.82f * 3.14159f, 8, th, blk, z); break;
    case MO_FROWN: em_arc(cx, my + r * 0.30f, r * 0.30f, r * 0.24f, 1.17f * 3.14159f, 1.83f * 3.14159f, 8, th, blk, z); break;
    case MO_OPEN:  em_ell(cx, my - r * 0.16f, r * 0.46f, r * 0.46f, 0.0f, 3.14159f, 10, blk, z);
                   em_ell(cx, my + r * 0.12f, r * 0.24f, r * 0.14f, 3.14159f, PI2, 8, red, z); break;
    case MO_BIG:   em_ell(cx, my + r * 0.08f, r * 0.34f, r * 0.38f, 0.0f, PI2, 12, blk, z); break;
    case MO_YAWN:  em_ell(cx, my + r * 0.05f, r * 0.24f, r * 0.30f, 0.0f, PI2, 12, blk, z); break;
    case MO_O:     em_ell(cx, my + r * 0.06f, r * 0.12f, r * 0.17f, 0.0f, PI2, 8, blk, z); break;
    case MO_FLAT:  em_line(cx - r * 0.28f, my + r * 0.05f, cx + r * 0.28f, my + r * 0.05f, th, blk, z); break;
    case MO_WAVY:  em_zig(cx, my + r * 0.05f, r * 0.34f, r * 0.05f, 6, th, blk, z); break;
    case MO_ZIG:   em_zig(cx, my + r * 0.10f, r * 0.34f, r * 0.10f, 6, th, blk, z); break;
    case MO_TONGUE:
        em_ell(cx + r * 0.10f, my + r * 0.12f, r * 0.13f, r * 0.17f, 0.0f, 3.14159f, 8, red, z);
        em_line(cx - r * 0.34f, my, cx + r * 0.34f, my, th, blk, z); break;
    case MO_SMIRK:
        em_line(cx - r * 0.28f, my + r * 0.07f, cx + r * 0.05f, my + r * 0.07f, th, blk, z);
        em_line(cx + r * 0.05f, my + r * 0.07f, cx + r * 0.30f, my - r * 0.02f, th, blk, z); break;
    }
}

static void draw_emoji_menu(void)                                       // menu de emojis (flecha derecha)
{
    float cs = fminf(52.0f, (H - 70.0f) / 6.0f), gw = cs * 5.0f, gh = cs * 6.0f;
    float x0 = (W - gw) * 0.5f, y0 = (H - gh) * 0.5f - 6.0f;
    const u64 sel_c = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0);
    gsKit_prim_sprite(gsGlobal, x0 - 6.0f, y0 - 6.0f, x0 + gw + 6.0f, y0 + gh + 6.0f, 16777100, sel_c);
    gsKit_prim_sprite(gsGlobal, x0 - 4.0f, y0 - 4.0f, x0 + gw + 4.0f, y0 + gh + 4.0f, 16777110, GS_SETREG_RGBAQ(14, 12, 18, 0x80, 0));
    for (int i = 0; i < 30; i++) {
        float cx = x0 + (i % 5) * cs + cs * 0.5f, cy = y0 + (i / 5) * cs + cs * 0.5f;
        if (i == emoji_sel) gsKit_prim_sprite(gsGlobal, cx - cs * 0.5f, cy - cs * 0.5f, cx + cs * 0.5f, cy + cs * 0.5f, 16777120, GS_SETREG_RGBAQ(70, 66, 30, 0x80, 0));
        draw_emoji(cx, cy, cs * (i == emoji_sel ? 0.44f : 0.36f), i, 16777130);
    }
    draw_text_c(y0 - 22.0f > 2.0f ? y0 - 22.0f : 2.0f, "EMOJIS", 2, sel_c);
    draw_text_c(y0 + gh + 10.0f, "X: ENVIAR   O: CERRAR", 1, GS_SETREG_RGBAQ(190, 190, 195, 0x80, 0));
}

// ---- Bailes (flecha izquierda): 30 casillas, por ahora 5 con nombre; las demas quedan libres ----
#define N_DANCES 4
static const char *dance_names[30] = { "FLAIR", "BREAKDANCE 1990", "TWERK", "GANGNAM STYLE", 0 };

static void draw_dance_menu(void)
{
    float cs = fminf(52.0f, (H - 70.0f) / 6.0f), gw = cs * 5.0f, gh = cs * 6.0f;
    float x0 = (W - gw) * 0.5f, y0 = (H - gh) * 0.5f - 6.0f;
    const u64 sel_c = GS_SETREG_RGBAQ(120, 220, 255, 0x80, 0);
    gsKit_prim_sprite(gsGlobal, x0 - 6.0f, y0 - 6.0f, x0 + gw + 6.0f, y0 + gh + 6.0f, 16777100, sel_c);
    gsKit_prim_sprite(gsGlobal, x0 - 4.0f, y0 - 4.0f, x0 + gw + 4.0f, y0 + gh + 4.0f, 16777110, GS_SETREG_RGBAQ(14, 12, 18, 0x80, 0));
    for (int i = 0; i < 30; i++) {
        float cx = x0 + (i % 5) * cs + cs * 0.5f, cy = y0 + (i / 5) * cs + cs * 0.5f;
        float h = cs * 0.5f - 1.0f;
        int used = i < N_DANCES;
        gsKit_prim_sprite(gsGlobal, cx - h, cy - h, cx + h, cy + h, 16777120,
                          i == dance_sel ? GS_SETREG_RGBAQ(30, 70, 90, 0x80, 0) : (used ? GS_SETREG_RGBAQ(28, 30, 40, 0x80, 0) : GS_SETREG_RGBAQ(20, 20, 26, 0x80, 0)));
        if (used) {                                                  // figura palito con los brazos arriba (icono provisional)
            float r = cs * 0.30f;
            u64 w = GS_SETREG_RGBAQ(235, 235, 240, 0x80, 0);
            em_line(cx, cy - r * 0.55f, cx, cy + r * 0.25f, 2.0f, w, 16777130);
            em_line(cx, cy - r * 0.35f, cx - r * 0.7f, cy - r * 0.9f, 2.0f, w, 16777130);
            em_line(cx, cy - r * 0.35f, cx + r * 0.7f, cy - r * 0.9f, 2.0f, w, 16777130);
            em_line(cx, cy + r * 0.25f, cx - r * 0.45f, cy + r * 0.95f, 2.0f, w, 16777130);
            em_line(cx, cy + r * 0.25f, cx + r * 0.45f, cy + r * 0.95f, 2.0f, w, 16777130);
            em_line(cx - r * 0.12f, cy - r * 0.9f, cx + r * 0.12f, cy - r * 0.9f, 3.0f, w, 16777130);
        }
    }
    draw_text_c(y0 - 22.0f > 2.0f ? y0 - 22.0f : 2.0f, "BAILES", 2, sel_c);
    const char *nm = (dance_sel < 30 && dance_names[dance_sel]) ? dance_names[dance_sel] : "LIBRE";
    draw_text_c(y0 + gh + 8.0f, nm, 2, GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0));
    draw_text_c(y0 + gh + 28.0f, "X: BAILAR   O: CERRAR", 1, GS_SETREG_RGBAQ(190, 190, 195, 0x80, 0));
}

// El emoji del otro jugador flota sobre su cabeza; el tuyo se ve arriba al centro de tu pantalla
static void draw_emoji_world(void)
{
    if (emoji_id >= 0 && (emoji_t > 0.8f || ((int)(emoji_t * 10.0f) & 1)))
        draw_emoji(W * 0.5f, 34.0f, 15.0f, emoji_id, 16777100);
    if (num_players < 2) return;
    const Player *Q = &P[1 - pl_cur];
    if (Q->emoji_id < 0 || Q->cur_layer != cur_layer || Q->climbing || climbing) return;
    if (!(Q->emoji_t > 0.8f || ((int)(Q->emoji_t * 10.0f) & 1))) return;
    float wx = Q->px, wz = Q->pz, wy = Q->foot_y + Q->jump_h + 2.25f - 0.6f * Q->crouch_f + (cur_layer ? SEWER_Y : 0.0f);
    float dx = wx - px, dz = wz - pz, vx = dx * rx + dz * rz, vz = dx * fx + dz * fz, vy = wy - cam_y;
    float yy = vy * cpitch - vz * spitch, zz = vy * spitch + vz * cpitch;
    if (zz < 0.5f || !los_to(wx, wz, 0.0f)) return;
    float sx = W * 0.5f + vx / zz * FOCAL, sy = H * 0.5f - yy / zz * FOCAL;
    float r = clampf(0.30f / zz * FOCAL, 7.0f, 44.0f);
    if (sx < -r || sx > W + r || sy < -r || sy > H + r) return;
    draw_emoji(sx, sy, r, Q->emoji_id, 16777090);
}

static void draw_code_ui(void)                                  // ventana del candado (4 digitos)
{
    float bw = 280.0f, bh = 108.0f;
    float x0 = floorf((W - bw) * 0.5f), y0 = floorf(H * 0.45f - bh * 0.5f);
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), gc = GS_SETREG_RGBAQ(120, 120, 126, 0x80, 0);
    gsKit_prim_sprite(gsGlobal, x0 - 2.0f, y0 - 2.0f, x0 + bw + 2.0f, y0 + bh + 2.0f, 16777200, yc);
    gsKit_prim_sprite(gsGlobal, x0, y0, x0 + bw, y0 + bh, 16777200, GS_SETREG_RGBAQ(22, 18, 16, 0x80, 0));
    draw_text_c(y0 + 8.0f, "CANDADO", 2, yc);
    for (int i = 0; i < 4; i++) {
        float bx = W * 0.5f - 90.0f + (float)i * 48.0f, by = y0 + 30.0f;
        int sel = (i == code_pos);
        gsKit_prim_sprite(gsGlobal, bx - 2.0f, by - 2.0f, bx + 38.0f, by + 46.0f, 16777200, sel ? yc : gc);
        gsKit_prim_sprite(gsGlobal, bx, by, bx + 36.0f, by + 44.0f, 16777200, GS_SETREG_RGBAQ(8, 8, 10, 0x80, 0));
        int pw = 1;
        for (int k = 0; k < 3 - i; k++) pw *= 10;
        char dg[2] = { (char)('0' + (code_val / pw) % 10), '\0' };
        draw_text(bx + 8.0f, by + 8.0f, dg, 4, sel ? yc : GS_SETREG_RGBAQ(235, 235, 235, 0x80, 0));
    }
    draw_text_c(y0 + 82.0f, "ARRIBA/ABAJO: NUMERO   IZQ/DER: CASILLA", 1, gc);
    draw_text_c(y0 + 94.0f, "X: ABRIR   O: SALIR", 1, gc);
}

static void draw_inventory(void)                                // R1 (mantener): llaves y codigos
{
    float bw = 300.0f, bh = 104.0f;
    float x0 = floorf((W - bw) * 0.5f), y0 = floorf(H * 0.40f - bh * 0.5f);
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), wc = GS_SETREG_RGBAQ(225, 225, 230, 0x80, 0), gc = GS_SETREG_RGBAQ(95, 95, 100, 0x80, 0);
    gsKit_prim_sprite(gsGlobal, x0 - 1.0f, y0 - 1.0f, x0 + bw + 1.0f, y0 + bh + 1.0f, 16777200, gc);
    gsKit_prim_sprite(gsGlobal, x0, y0, x0 + bw, y0 + bh, 16777200, GS_SETREG_RGBAQ(18, 16, 15, 0x80, 0));
    draw_text(x0 + 12.0f, y0 + 8.0f, "LLAVES", 2, yc);
    draw_text(x0 + 160.0f, y0 + 8.0f, "CODIGOS", 2, yc);
    for (int i = 0; i < 4; i++) {
        float y = y0 + 32.0f + (float)i * 15.0f;
        u64 c = carry == i + 1 ? GS_SETREG_RGBAQ((int)key_rgb[i][0], (int)key_rgb[i][1], (int)key_rgb[i][2], 0x80, 0) : GS_SETREG_RGBAQ(50, 50, 52, 0x80, 0);
        gsKit_prim_sprite(gsGlobal, x0 + 12.0f, y, x0 + 24.0f, y + 9.0f, 16777200, c);
        draw_text(x0 + 30.0f, y + 1.0f, key_name[i], 1, carry == i + 1 ? wc : gc);
    }
    for (int i = 0; i < 2; i++) {
        char b[32];
        if (have_code[i]) snprintf(b, sizeof b, "%s: %04d", code_name[i], code_num[i]);
        else snprintf(b, sizeof b, "%s: ????", code_name[i]);
        draw_text(x0 + 160.0f, y0 + 34.0f + (float)i * 16.0f, b, 1, have_code[i] ? wc : gc);
    }
}

static void draw_door_hud(void)
{
    u64 yc = GS_SETREG_RGBAQ(255, 230, 80, 0x80, 0), rc = GS_SETREG_RGBAQ(255, 120, 100, 0x80, 0), gc = GS_SETREG_RGBAQ(160, 160, 166, 0x80, 0);
    for (int i = 0; i < 4; i++) {                               // llaves que llevas (casillas pequenas)
        u64 c = carry == i + 1 ? GS_SETREG_RGBAQ((int)key_rgb[i][0], (int)key_rgb[i][1], (int)key_rgb[i][2], 0x80, 0) : GS_SETREG_RGBAQ(45, 45, 47, 0x80, 0);
        gsKit_prim_sprite(gsGlobal, 19.0f + i * 20.0f, 79.0f, 35.0f + i * 20.0f, 89.0f, 16777000, BLACK);
        gsKit_prim_sprite(gsGlobal, 20.0f + i * 20.0f, 80.0f, 34.0f + i * 20.0f, 88.0f, 16777010, c);
    }
    draw_text(20.0f, 94.0f, "R1: NOTAS", 1, gc);
    int dn = (map_open || code_door >= 0) ? -1 : door_near();
    if (dn >= 0) draw_text_c(H - 34.0f, doors[dn].type == 1 ? "CUADRADO: PONER CODIGO" : "CUADRADO: ABRIR PUERTA", 2, yc);
    if (door_msg > 0 && door_msg_id) {
        char b[48];
        msg_text(door_msg_id, b, (int)sizeof b);
        draw_text_c(H - 62.0f, b, 2, (door_msg_id <= 4 || door_msg_id == 10 || door_msg_id == 13) ? rc : yc);
        if (door_msg_id >= 20 && door_msg_id < 40) draw_text_c(H - 44.0f, "R1: VER NOTAS", 1, gc);
    }
    {   // luz UV: aviso fijo y barra de carga mientras mantienes L2
        u64 uc = GS_SETREG_RGBAQ(190, 110, 255, 0x80, 0);
        if (uv_on && flash_on) draw_text(20.0f, 106.0f, "LUZ UV", 1, uc);
        if (mon_uv_t > 0.05f && mon_blind_t <= 0.0f) {                      // le estas apuntando con la UV: barra de ceguera
            float bw = 64.0f, x0 = W * 0.5f - bw * 0.5f, y0 = H * 0.62f;
            gsKit_prim_sprite(gsGlobal, x0 - 1.0f, y0 - 1.0f, x0 + bw + 1.0f, y0 + 6.0f, 16777000, BLACK);
            gsKit_prim_sprite(gsGlobal, x0, y0, x0 + bw * (mon_uv_t / 3.0f), y0 + 5.0f, 16777010, GS_SETREG_RGBAQ(190, 110, 255, 0x80, 0));
            draw_text_c(y0 - 12.0f, "CEGANDO", 1, uc);
        }
        if (uv_hold > 0.0f && uv_hold < 1.0f) {
            float bw = 64.0f, x0 = W * 0.5f - bw * 0.5f, y0 = H - 22.0f;
            gsKit_prim_sprite(gsGlobal, x0 - 1.0f, y0 - 1.0f, x0 + bw + 1.0f, y0 + 6.0f, 16777000, BLACK);
            gsKit_prim_sprite(gsGlobal, x0, y0, x0 + bw * uv_hold, y0 + 5.0f, 16777010, GS_SETREG_RGBAQ(150, 70, 255, 0x80, 0));
            draw_text_c(y0 - 12.0f, uv_on ? "LUZ NORMAL" : "LUZ UV", 1, uc);
        }
    }
    if (inv_open) draw_inventory();
    if (code_door >= 0) draw_code_ui();
    if (spec_mode) draw_text_c(8.0f, "MODO ESPECTADOR   X: SUBIR   CUADRADO: BAJAR   R2: RAPIDO", 1, GS_SETREG_RGBAQ(150, 220, 255, 0x80, 0));
    if (emoji_open) draw_emoji_menu();
    if (dance_open) draw_dance_menu();
}

static void render_game_inner(float t, int moving, int near_ladder, int notes)
{
        if (state == 1) {                                  // JUMPSCARE
            u64 bgc = (js_t < 4) ? GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0)
                    : ((js_t < 100 && ((js_t / 2) & 1)) ? GS_SETREG_RGBAQ(90, 0, 0, 0x80, 0) : BLACK);
            gsKit_clear(gsGlobal, bgc);
            if (js_t < 100) draw_monster(t);
        }
        else if (state == 2) {                             // FIN
            gsKit_clear(gsGlobal, BLACK);
            int a = 600 - state_timer; if (a > 120) a = 120;
            int g = 255 * a / 120;
            u64 fc = GS_SETREG_RGBAQ(g, g, g, 0x80, 0), sc = GS_SETREG_RGBAQ(g * 3 / 4, g, g * 3 / 4, 0x80, 0);
            draw_text_c(H * 0.28f, "FIN", 8, fc);
            draw_text_c(H * 0.28f + 80.0f, "LA PUERTA SE CIERRA DETRAS DE TI...", 2, sc);
            draw_text_c(H * 0.28f + 104.0f, "ESCAPASTE DEL BOSQUE", 2, sc);
            draw_text_c(H * 0.28f + 150.0f, "GRACIAS POR JUGAR", 2, fc);
        }
        else if (map_open) draw_map_screen();                 // mapa abierto: solo se ve el mapa
        else {
            lights_prepare();
            gsKit_clear(gsGlobal, SKY);
            draw_stars();
            if (climbing) { draw_layer(0); draw_layer(1); }
            else draw_layer(cur_layer);
            if (cur_layer == 0 && !climbing) draw_trees();
            draw_props(t);
            draw_pumps();
            draw_supermarket(t);
            draw_graves();
            draw_church();
            draw_candles();
            draw_chimney();
            draw_rocks();
            draw_lamps();
            draw_map_board(t);
            draw_lockers();
            draw_doors();
            draw_items(t);
            draw_shafts();

            for (int i = 0; i < 3; i++) {
                if (notes_off[i] || (int)notes_pos[i][3] != cur_layer) continue;
                if (in_view(notes_pos[i][0], notes_pos[i][1], 0.8f, (gfx_pd[gfx] * rd_k)))
                    draw_key_floor(notes_pos[i][0], notes_pos[i][1], key_ang[i], 5 + i);
            }
            draw_other_player(t);                       // el otro jugador (pantalla dividida)
            if (dance_cam) draw_self_model();           // tu cuerpo bailando
            draw_emoji_world();                         // emojis (el tuyo arriba al centro, el del otro sobre su cabeza)
            if (mlayer == cur_layer && !climbing && in_view(sx_, sz_, 2.2f, 26.0f)) draw_monster(t);   // si no lo miras, ni se calcula

            gsKit_set_primalpha(gsGlobal, BLEND_STD, 0);
            gsGlobal->PrimAlphaEnable = GS_SETTING_ON;
            draw_sewer_water(t);
            draw_spot_overlay();
            draw_glows(t);
            draw_other_beam();                          // el circulo de luz del otro jugador
            gsGlobal->PrimAlphaEnable = GS_SETTING_OFF;

            if (!dance_cam) { draw_flashlight(t, moving);
            draw_detector(t); draw_key_hand(t); }                           // el radio que marca la distancia al monstruo

            if (num_players == 2)                          // quien es quien en pantalla dividida
                draw_text_c(6.0f, net_online ? net_names[pl_cur] : (pl_cur ? "J2" : "J1"), 2, pl_cur ? GS_SETREG_RGBAQ(70, 150, 255, 0x80, 0) : GS_SETREG_RGBAQ(235, 40, 36, 0x80, 0));
            for (int i = 0; i < 3; i++) {                 // HUD: notas
                u64 c = notes_got[i] ? GS_SETREG_RGBAQ(150, 230, 255, 0x80, 0)
                                     : GS_SETREG_RGBAQ(50, 50, 50, 0x80, 0);
                gsKit_prim_sprite(gsGlobal, 20.0f + i * 24.0f, 20.0f, 36.0f + i * 24.0f, 36.0f, 16777000, c);
            }
            {                                                   // HUD: estamina
                u64 ol = GS_SETREG_RGBAQ(0, 0, 0, 0x80, 0), bg = GS_SETREG_RGBAQ(35, 35, 35, 0x80, 0);
                u64 fg = exhausted ? (((frame_no / 8) & 1) ? GS_SETREG_RGBAQ(220, 60, 40, 0x80, 0)
                                                           : GS_SETREG_RGBAQ(120, 40, 30, 0x80, 0))
                                   : (stamina < 0.3f ? GS_SETREG_RGBAQ(230, 190, 60, 0x80, 0)
                                                     : GS_SETREG_RGBAQ(90, 210, 110, 0x80, 0));
                gsKit_prim_sprite(gsGlobal, 18.0f, 42.0f, 182.0f, 56.0f, 16777000, ol);
                gsKit_prim_sprite(gsGlobal, 20.0f, 44.0f, 180.0f, 54.0f, 16777000, bg);
                if (stamina > 0.01f)
                    gsKit_prim_sprite(gsGlobal, 20.0f, 44.0f, 20.0f + 160.0f * stamina, 54.0f, 16777000, fg);
            }
            draw_map_hud();
            draw_door_hud();
            draw_locker_hud();
            if (near_ladder >= 0 && !climbing && ((frame_no / 20) & 1)) {   // aviso: pulsa X
                u64 wc = GS_SETREG_RGBAQ(255, 255, 255, 0x80, 0);
                float bx = W * 0.5f, by = H - 70.0f;
                if (cur_layer == 0)
                    gsKit_prim_triangle_gouraud_3d(gsGlobal, bx - 16, by, 16777000, bx + 16, by, 16777000, bx, by + 26, 16777000, wc, wc, wc);
                else
                    gsKit_prim_triangle_gouraud_3d(gsGlobal, bx - 16, by + 26, 16777000, bx + 16, by + 26, 16777000, bx, by, 16777000, wc, wc, wc);
            }
        }
}

