static void prev_draw(float x, float y, float w, float h)     // imagen de vista previa del mapa
{
    if (!prev_ok) {
        prev_tex.Width = 256; prev_tex.Height = 128; prev_tex.PSM = GS_PSM_CT16; prev_tex.Mem = (void *)prev_img; prev_tex.Filter = GS_FILTER_LINEAR;
        prev_tex.Vram = gsKit_vram_alloc(gsGlobal, gsKit_texture_size(256, 128, GS_PSM_CT16), GSKIT_ALLOC_USERBUFFER);
        gsKit_texture_upload(gsGlobal, &prev_tex);
        prev_ok = 1;
    }
    gsKit_prim_sprite_texture(gsGlobal, &prev_tex, x, y, 0.0f, 0.0f, x + w, y + h, 256.0f, 128.0f, 16777000, GS_SETREG_RGBAQ(128, 128, 128, 0x80, 0));
}

// sel: 0 dificultad, 1 marcador, 2 vista previa (solo en 1/2 jugadores), 3 boton
static void setup_ui(const char *title, int sel, int diff, int diff_locked, const char *btn, int btn_on, u64 title_col)
{
    static const char *dn_[3] = { "FACIL", "NORMAL", "DIFICIL" };
    u64 sel_c = GS_SETREG_RGBAQ(255, 230, 90, 0x80, 0);
    u64 pbg = GS_SETREG_RGBAQ(16, 16, 18, 0x80, 0), pbd = GS_SETREG_RGBAQ(70, 70, 76, 0x80, 0);
    u64 white = GS_SETREG_RGBAQ(235, 235, 238, 0x80, 0), red = GS_SETREG_RGBAQ(225, 20, 20, 0x80, 0), arr = GS_SETREG_RGBAQ(150, 150, 155, 0x80, 0);
    (void)title_col;
    draw_text(24.0f, 22.0f, title, 3, white);
    for (int i = 0; i < 2; i++) {                         // paneles de opciones (arriba a la derecha)
        float x0 = W * 0.50f, x1 = W - 20.0f, y0 = 20.0f + i * 50.0f, y1 = y0 + 42.0f;
        u64 bd = (i == sel) ? sel_c : pbd;
        gsKit_prim_sprite(gsGlobal, x0 - 2.0f, y0 - 2.0f, x1 + 2.0f, y1 + 2.0f, 16776990, bd);
        gsKit_prim_sprite(gsGlobal, x0, y0, x1, y1, 16777000, pbg);
        const char *nm = i == 0 ? "DIFICULTAD" : "MARCADOR";
        const char *vl = i == 0 ? dn_[diff < 0 ? 0 : (diff > 2 ? 2 : diff)] : (map_ind ? "SI" : "NO");
        draw_text(x0 + 12.0f, y0 + 14.0f, nm, 2, white);
        float cx = x1 - 82.0f;
        if (!(i == 0 && diff_locked)) {
            draw_text(cx - 70.0f, y0 + 12.0f, "<", 3, arr);
            draw_text(x1 - 28.0f, y0 + 12.0f, ">", 3, arr);
        }
        draw_text(cx - (float)text_w(vl, 2) * 0.5f, y0 + 14.0f, vl, 2, red);
    }
    if (diff_locked) draw_text(W * 0.50f, 118.0f, "LA DIFICULTAD LA ELIGE EL ANFITRION", 1, arr);
    {   // vista previa del mapa (imagen) en un marco
        float mx = 34.0f, mw = 232.0f, mh = 116.0f, my = H - 70.0f - 16.0f - mh;
        u64 fc = sel == 2 ? sel_c : GS_SETREG_RGBAQ(205, 205, 210, 0x80, 0);
        gsKit_prim_sprite(gsGlobal, mx - 3.0f, my - 3.0f, mx + mw + 3.0f, my, 16776990, fc);
        gsKit_prim_sprite(gsGlobal, mx - 3.0f, my + mh, mx + mw + 3.0f, my + mh + 3.0f, 16776990, fc);
        gsKit_prim_sprite(gsGlobal, mx - 3.0f, my, mx, my + mh, 16776990, fc);
        gsKit_prim_sprite(gsGlobal, mx + mw, my, mx + mw + 3.0f, my + mh, 16776990, fc);
        prev_draw(mx, my, mw, mh);
        draw_text(mx, my - 16.0f, "MAPA: PUEBLO", 1, arr);
    }
    {   // boton verde
        float bx = 28.0f, by = H - 70.0f, bw = 250.0f, bh = 46.0f;
        u64 bd = sel == 3 ? sel_c : GS_SETREG_RGBAQ(230, 230, 232, 0x80, 0);
        gsKit_prim_sprite(gsGlobal, bx - 3.0f, by - 3.0f, bx + bw + 3.0f, by + bh + 3.0f, 16776990, bd);
        gsKit_prim_sprite(gsGlobal, bx, by, bx + bw, by + bh, 16777000, btn_on ? GS_SETREG_RGBAQ(40, 150, 40, 0x80, 0) : GS_SETREG_RGBAQ(60, 70, 60, 0x80, 0));
        draw_text(bx + (bw - (float)text_w(btn, 2)) * 0.5f, by + 16.0f, btn, 2, btn_on ? white : arr);
    }
}

static void menu_bg_main(void)
{
    cam_rc = 1.0f; cam_rs = 0.0f;
    px = 0.0f; pz = 0.0f; yaw = 0.0f; pitch = 0.0f; cpitch = 1.0f; spitch = 0.0f;
    fx = 0.0f; fz = 1.0f; rx = 1.0f; rz = 0.0f; cam_y = 1.5f; foot_y = 0.0f;
    flash_on = 1; amb_r = 30.0f; light_flick = 1.0f; cur_layer = 0; climbing = 0;
    sx_ = 1.0f; sz_ = 3.6f; mon_y = 0.0f; mon_spd = 1.6f; mon_runf = 0.0f; mon_phase += 1.6f * (1.0f / 60.0f) * 3.0f;
    gsKit_clear(gsGlobal, SKY);
    draw_stars();
    draw_monster(0.0f);
    gsKit_set_primalpha(gsGlobal, BLEND_STD, 0);         // el haz de la linterna tambien en el menu:
    gsGlobal->PrimAlphaEnable = GS_SETTING_ON;           // si el circulo sale oscuro, usa INVERTIR LUZ
    draw_spot_overlay();
    gsGlobal->PrimAlphaEnable = GS_SETTING_OFF;
}

static void menu_dim(void)       // oscurece la pantalla (fondo de pausa)
{
    gsKit_set_primalpha(gsGlobal, BLEND_STD, 0);
    gsGlobal->PrimAlphaEnable = GS_SETTING_ON;
    gsKit_prim_sprite(gsGlobal, 0.0f, 0.0f, W, H, 16777200, GS_SETREG_RGBAQ(0, 0, 0, ba(86), 0));
    gsGlobal->PrimAlphaEnable = GS_SETTING_OFF;
}

static void render_game(float t, int moving, int near_ladder, int notes)
{
    if (dance_id < 0 || state != 0 || climbing || map_open || dance_open) { dance_cam = 0; render_game_inner(t, moving, near_ladder, notes); return; }
    // camara en tercera persona: delante de ti, mirandote
    float spx = px, spz = pz, sfx_ = fx, sfz_ = fz, srx = rx, srz = rz, scy = cam_y, scp = cpitch, ssp = spitch, sroll_c = cam_rc, sroll_s = cam_rs;
    float dir_x = sinf(yaw), dir_z = cosf(yaw), D = 4.6f;
    while (D > 1.2f && blocked(px + dir_x * D, pz + dir_z * D, 0.4f)) D -= 0.3f;
    px = spx + dir_x * D; pz = spz + dir_z * D;
    fx = -dir_x; fz = -dir_z; rx = -cosf(yaw); rz = sinf(yaw);
    cpitch = cosf(0.10f); spitch = sinf(0.10f); cam_rc = 1.0f; cam_rs = 0.0f;
    cam_y = foot_y + jump_h + 2.0f;
    dance_cam = 1;
    dance_px = spx; dance_pz = spz;
    render_game_inner(t, 0, -1, notes);
    dance_cam = 0;
    px = spx; pz = spz; fx = sfx_; fz = sfz_; rx = srx; rz = srz; cam_y = scy; cpitch = scp; spitch = ssp; cam_rc = sroll_c; cam_rs = sroll_s;
}

// Dibuja un cuadro de juego: pantalla completa (1 jugador) o dividida (2 jugadores)
static void render_frame(float t, int paused)
{
    int notes = notes_got[0] + notes_got[1] + notes_got[2];
    if (num_players < 2 || state != 0 || net_online) {   // 1 jugador, online, jumpscare o final: pantalla completa
        int pi = (num_players == 2 && state == 1) ? js_victim : (net_online ? net_local : 0);
        view_full();
        player_load(pi);
        render_game(t, paused ? 0 : p_moving, paused ? -1 : p_near, notes);
        view_full();
        return;
    }
    int hh = (int)(SH * 0.5f);                           // J1 arriba, J2 abajo
    for (int i = 0; i < 2; i++) {
        player_load(i);
        if (i == 0) view_set(0.0f, 0.0f, SW, (float)(hh - 1));
        else        view_set(0.0f, (float)(hh + 1), SW, SH - (float)(hh + 1));
        render_game(t, paused ? 0 : p_moving, paused ? -1 : p_near, notes);
    }
    view_full();
    gsKit_prim_sprite(gsGlobal, 0.0f, (float)(hh - 1), SW, (float)(hh + 1), 16777000, GS_SETREG_RGBAQ(0, 0, 0, 0x80, 0));   // linea divisoria
}

static int pad2_ready(void)                              // hay un control en el puerto 2?
{
    int s = padGetState(1, 0);
    return s == PAD_STATE_STABLE || s == PAD_STATE_FINDCTP1;
}
static int pad2_warn;

static void start_game(int players)
{
    num_players = players;
    if (players == 2) padSetMainMode(1, 0, PAD_MMODE_DUALSHOCK, PAD_MMODE_LOCK);
    reset_game();
    spec_mode = spec_pending; spec_pending = 0;
    screen = SC_PLAY;
}

